def convert_to_spy(examples): 
    spy_examples = []
    py_examples = []
    for sample in examples['content']:
        try:
            first_line = re_first_line.match(sample).group()
        except:
            continue

        if first_line.startswith('<'):
            sample = re_first_line.sub('', sample) 

