func TestKVCache_SetGet(t *testing.T) {
	c := newTestCache()
	c.Set("foo", "bar")
	got, ok := c.Get("foo")
	if !ok || got != "bar" {
		t.Fatalf("Get(foo) = %q, %v; want bar, true", got, ok)
	}
