package taskpkg

import "strings"

// SplitPath splits a slash-separated path into its components, dropping empty
// segments (so "//a//b//" → ["a","b"]).
func SplitPath(p string) []string {
	var out []string
	for _, seg := range strings.Split(p, "/") {
		if seg != "" {
			out = append(out, seg)
		}
	}
	return out
}

// JoinPath joins segments with single slashes, ignoring empty segments.
func JoinPath(segs ...string) string {
	var nonEmpty []string
	for _, s := range segs {
		if s != "" {
			nonEmpty = append(nonEmpty, s)
		}
	}
	return strings.Join(nonEmpty, "/")
}

// HasExt reports whether p ends with the extension ext (which should include
// the leading dot, e.g. ".go").
func HasExt(p, ext string) bool {
	return strings.HasSuffix(p, ext)
}

package taskpkg

import (
	"reflect"
	"testing"
)

func TestSplitPath(t *testing.T) {
	cases := []struct {
		in   string
		want []string
	}{
		{"a/b/c", []string{"a", "b", "c"}},
		{"//a//b//", []string{"a", "b"}},
		{"", nil},
		{"single", []string{"single"}},
	}
	for _, c := range cases {
		got := SplitPath(c.in)
		if len(got) == 0 && len(c.want) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("SplitPath(%q) = %v want %v", c.in, got, c.want)
		}
	}
}

func TestJoinPath(t *testing.T) {
	if got := JoinPath("a", "b", "c"); got != "a/b/c" {
		t.Errorf("got %q want a/b/c", got)
	}
	if got := JoinPath("a", "", "b"); got != "a/b" {
		t.Errorf("got %q want a/b", got)
	}
}

func TestHasExt(t *testing.T) {
	if !HasExt("foo.go", ".go") {
		t.Error("foo.go should HasExt .go")
	}
	if HasExt("foo.txt", ".go") {
		t.Error("foo.txt should not HasExt .go")
	}
}

